    {"ip": "10.42.11.18", "hostname": "jumphost-prod-01", "inferred_role": "target_jumphost_internet_exposed_rdp", "first_seen": "2027-09-14T03:14:08+0000", "last_seen": "2027-09-18T03:14:51+0000"}
